var datum, txt, Reboot_Timer, Fault_Reboot_Timer, Counter_Reboot_Timer;

// Beschreibe diese Funktion …
async function Logfile(datum, txt) {
    if (getState('0_userdata.0.go-e_V4.DebugAktiv_V4').val) {
      require('fs').appendFileSync('/opt/iobroker/log/' + datum + ' - go_E_V4.log', formatDate(new Date(), "hh:mm:ss") + " \t" + txt + "\n");}
}


// ------->>>> Logfile

// ------->> Verbindung überwachen
// WLan
on({ id: 'go-e.1.info.connection' /* If communication with circuit works */, change: 'ne' }, async (obj) => {
  let value = obj.state.val;
  let oldValue = obj.oldState.val;
  if ((obj.state ? obj.state.val : '') == true) {
    await Logfile(formatDate(new Date(), 'YYYY.MM.DD'), 'Überwachung / Wlan Verbindung wieder hergestellt.');
    sendTo('telegram.0', 'send', {
      text: 'go-e V4 / --> Wlan Verbindung wieder hergestellt',
    });
  } else {
    await Logfile(formatDate(new Date(), 'YYYY.MM.DD'), 'Überwachung / Wlan Verbindung verloren!');
    sendTo('telegram.0', 'send', {
      text: 'go-e V4 / --> Wlan Verbindung verloren !',
    });
  }
});
// Kommunikation
Reboot_Timer = getState('go-e.1.reboot_timer').val;
Fault_Reboot_Timer = false;
on({ id: 'go-e.1.reboot_timer' /* reboot_timer (rbtz) */, change: 'ne' }, async (obj) => {
  let value = obj.state.val;
  let oldValue = obj.oldState.val;
  Reboot_Timer = getState('go-e.1.reboot_timer').val;
  Counter_Reboot_Timer = 0;
  if (Fault_Reboot_Timer) {
    Fault_Reboot_Timer = false;
    await Logfile(formatDate(new Date(), 'YYYY.MM.DD'), 'Überwachung / Verbindung wieder hergestellt (Reboot Timer)!');
    sendTo('telegram.0', 'send', {
      text: 'go-e V4 / --> Verbindung wieder hergestellt (Reboot Timer) !',
    });
  }
});
schedule("* * * * * *", async () => {
  Counter_Reboot_Timer = (typeof Counter_Reboot_Timer === 'number' ? Counter_Reboot_Timer : 0) + 1;
  if ((Counter_Reboot_Timer >= 120) && (getState('go-e.1.reboot_timer').val == Reboot_Timer) && (!Fault_Reboot_Timer)) {
    Fault_Reboot_Timer = true;
    await Logfile(formatDate(new Date(), 'YYYY.MM.DD'), 'Überwachung / Verbindung verloren (Reboot Timer)!');
    sendTo('telegram.0', 'send', {
      text: 'go-e V4 / --> Verbindung verloren (Reboot Timer) !',
    });
  }
});


